def compute(vars):
    v1 = vars["v1"]
    v2 = vars["v2"]
    total_change = v1 + v2

    return {
        "value": total_change,
        "trace": {
            "v1": v1,
            "v2": v2,
            "total_change": total_change,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
